// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      answersUrl: 'assets/medvezhonok/' + year + '/' + grade + '-answers.pdf',
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2009, "4-5", [{"author":"А. Бердичевский","question":"Даны фрагменты стихотворения Юлиана Тувима «Азбука» в переводе Сергея Михалкова. Вместо некоторых букв стоят звёздочки. Вместо каких?\nАЗБУКА\nЧто случилось? Что случилось?\nС печки азбука свалилась!\n…\nФ, бедняжку, так раздуло —\nНе прочесть её никак!\nБукву * перевернуло —\nПревратило в мягкий знак!\nБуква * совсем сомкнулась —\nПревратилась в букву *.\nБуква А, когда очнулась,\nНе узнала никого!","choices":["<em>Р</em>, <em>С</em>, <em>О</em>","<em>Ь</em>, <em>С</em>, <em>О</em>","<em>Р</em>, <em>Б</em>, <em>В</em>","<em>Ъ</em>, <em>Э</em>, <em>О</em>","<em>Р</em>, <em>М</em>, <em>И</em>."],"key":"А","review":["Азбука упала с печки","У «Р» прямая ножка слева, а округлая часть вверху. Если перенести верхнюю часть вниз, оставив ножку слева, получится мягкий знак «Ь».","У «С» есть разрыв справа. Если концы буквы сомкнутся, она станет овальной «О». По порядку пропущены «Р», «С» и «О»."]},{"author":"Н. Валеева","question":"Дом — крыша, человек — голова, гриб — ...?","choices":["ножка","суп","корзинка","мухомор","шляпка."],"key":"Д","review":["Дом, человек и гриб","Крыша находится наверху дома, а голова наверху тела. Значит, нужна верхняя часть гриба.","Вверху у гриба шляпка, ножка — под ней. Мухомор целиком является грибом, а суп и корзинка вообще не его части."]},{"author":"Н. Валеева","question":"Какое из данных слов по составу отличается от остальных?","choices":["<em>словарь</em>","<em>январь</em>","<em>букварь</em>","<em>дикарь</em>","<em>аптекарь</em>."],"key":"Б","review":["Части пяти слов","Сравни «словарь» со «словом», «букварь» с «буквой», «дикарь» с «диким», «аптекарь» с «аптекой». После корня в каждом слове остаётся «-арь».","«Январь» — название месяца, и его корень включает «арь» целиком. Суффикса «-арь», выделенного в других словах, в нём нет."]},{"author":"Н. Валеева","question":"Даны части человеческого тела: нос, ухо, грудь, колено, рука. Что обычно не надевают ни на одну из них?","choices":["рукавицы","нагрудник","наколенники","наушники","носки."],"key":"Д","review":["Что куда надевают","Разложи предметы по списку: рукавицы на руки, нагрудник на грудь, наколенники на колени, наушники на уши.","Похожее звучание «нос» и «носки» может сбить с толку. Носки надевают на стопы, а стопы в список не вошли."]},{"author":"Е. Дмитриева","question":"Какое из этих слов может быть не только существительным, но и прилагательным?","choices":["<em>вожатый</em>","<em>водяной</em>","<em>леший</em>","<em>портной</em>","все эти слова могут быть только существительными."],"key":"Б","review":["Две роли одного слова","В сказке «водяной» — водяной дух, то есть персонаж. Здесь слово отвечает на вопрос «кто?» и выступает как существительное.","В выражении «водяной пар» то же слово отвечает на вопрос «какой?» и уточняет происхождение пара. Здесь оно прилагательное."]},{"author":"Е. Добрушина","question":"Из всех этих предложений вырезали приставки:\n(1) Котёнок __прыгнул со стола.\n(2) Котёнок __прыгнул из окна.\n(3) Котёнок __прыгнул на шкаф.\n(4) Котёнок __прыгнул через лужу.\n(5) Котёнок __прыгнул от меня.\nУкажите вырезанные приставки в правильном порядке.","choices":["<em>пере</em>-, <em>с</em>-, <em>за</em>-, <em>вс</em>-, <em>на</em>-","<em>с</em>-, <em>пере</em>-, <em>вс</em>-, <em>вы</em>-, <em>от</em>-","<em>от</em>-, <em>вы</em>-, <em>вс</em>-, <em>пере</em>-, <em>у</em>-","<em>с</em>-, <em>вы</em>-, <em>вс</em>-, <em>пере</em>-, <em>от</em>-","<em>вы</em>-, <em>с</em>-, <em>за</em>-, <em>вы</em>-, <em>ис</em>-."],"key":"Г","review":["Пять прыжков котёнка","Выбери приставки по направлению. Со стола котёнок «спрыгнул», из окна «выпрыгнул», на шкаф «вспрыгнул».","Через лужу он «перепрыгнул», от человека «отпрыгнул». Получилась цепочка «с-, вы-, вс-, пере-, от-»."]},{"author":"С. Бурлак","question":"Библиотекарь Д. Е. Фолиантов занимался расстановкой книг в шкафу номер 7. Что он делал с книгами?","choices":["расстаивал","расстановливал","расстановлял","расставливал","расставлял."],"key":"Д","review":["Книги в шкафу","Расстановка — это размещение на нужных местах. Можно сказать «библиотекарь расставил книги», если работа закончена.","О процессе говорят «расставлял». Проверь на фразе «он весь день расставлял книги по полкам»."]},{"author":"К. Гилярова","question":"Какое из этих слов не обозначает транспортное средство?","choices":["<em>теплоход</em>","<em>пароход</em>","<em>ледоход</em>","<em>снегоход</em>","<em>вездеход</em>."],"key":"В","review":["Слова на «-ход»","Теплоход и пароход — суда. Снегоход едет по снегу, а вездеход может ехать там, где трудно проехать обычной машине.","Ледоход — движение льдин по реке. Он происходит весной, когда лёд ломается, и не является машиной или судном."]},{"author":"И. Рубанов","question":"Маша составляла кроссворд. Ей осталось придумать вопрос для строки из трёх клеточек, где в первой клеточке уже стояла буква <em>м</em>, а в третьей — буква <em>ч</em>. Она попросила друзей помочь. Коля предложил вопрос: «<em>Холодное оружие</em>», Соня: «<em>То,</em> <em>чем играют в футбол</em>», а Катя: «<em>Встреча двух команд</em>». Кто из них дал плохой совет?","choices":["все трое","Коля","Соня","Катя","все советы хорошие."],"key":"Г","review":["Строка в кроссворде","Подбери ответы: холодное оружие — «меч», предмет для игры в футбол — «мяч». Оба заполняют строку «м_ч».","Встреча двух команд — «матч», с буквой «т» перед «ч». Ответу Кати нужно четыре клетки, поэтому её совет не подходит."]},{"author":"Н. Добрушина","question":"Дениске идёт девятый год. Это значит, что ему","choices":["больше девяти, но меньше десяти","больше восьми, но меньше девяти","больше семи, но меньше восьми","больше девяти","меньше восьми."],"key":"Б","review":["Текущий год жизни","Считай с рождения: до первого дня рождения идёт первый год, после него начинается второй.","Девятый год начинается после того, как ребёнку исполнилось восемь. Девятого дня рождения пока не было, так что возраст между восемью и девятью."]},{"author":"Е. Муравенко","question":"Из всех данных глаголов, кроме одного, убрав мягкий знак, можно получить существительные. Из какого глагола существительное таким образом не получается?","choices":["<em>быть</em>","<em>открыть</em>","<em>плакать</em>","<em>брать</em>","<em>молоть</em>."],"key":"Б","review":["Глаголы без мягкого знака","Убери конечный «ь» и узнай четыре названия: «быт», «плакат», «брат», «молот». Все они существительные.","Из «открыть» выходит «открыт». Так можно сказать «магазин открыт», но слово само по себе не называет предмет."]},{"author":"С. Бурлак","question":"Какое слово не родственно остальным?","choices":["<em>свинья</em>","<em>свинопас</em>","<em>свинец</em>","<em>свинство</em>","<em>свинарник</em>."],"key":"В","review":["Слова со «свин-»","Свинопас пасёт свиней, свинарник — место для свиней, а «свинство» переносит образ свиньи на неприятный поступок.","Свинец — название металла. В современном русском его не связывают со «свиньёй» как однокоренное слово."]},{"author":"О. Шеманаева","question":"… <em>ребёнок</em> , … <em>надпись</em>, … <em>конь</em>, … <em>юноша</em>.","choices":["<em>дарёный</em>, <em>дарственная</em>, <em>одарённый</em>, <em>даровитый</em>","<em>дарёный</em>, <em>даровитая</em>, <em>дарственный</em>, <em>одарённый</em>","<em>дарственный</em>, <em>даровитая</em>, <em>дарёный</em>, <em>одарённый</em>","<em>одарённый</em>, <em>дарственная</em>, <em>дарёный</em>, <em>даровитый</em>","<em>одарённый</em>, <em>даровитая</em>, <em>дарственный</em>, <em>дарёный</em>."],"key":"Г","review":["Четыре слова о даре","Надпись на подарке — «дарственная», а полученный в подарок конь — «дарёный». Это проверяется по выражению «дарёному коню в зубы не смотрят».","Талантливый ребёнок — «одарённый», талантливый юноша — «даровитый». В порядке пропусков получается «одарённый, дарственная, дарёный, даровитый»."]},{"author":"Л. Добрушин и Е. Добрушина","question":"Лёва играл с папой в войну. Себе в помощники он взял игрушечного щенка и придумал ему грозное имя: пусть папа испугается! Как ему записать это имя по правилам русского языка?","choices":["<em>Папагрыс</em>","<em>ПапоГрыз</em>","<em>Папогрыз</em>","<em>Папогрыс</em>","<em>ПапаГрыз</em>."],"key":"В","review":["Кличка игрушечного щенка","Лёва хочет напугать папу, так что имя складывается из «папа» и «грызть». Две основы «пап-» и «грыз» соединяются через «о».","Кличку начинают с заглавной, а внутри пишут строчные буквы. На конце сохраняется «з», как в «грызть»: «Папогрыз»."]},{"author":"С. Переверзева","question":"Чему <strong>не</strong> может равняться «де…ять умножить на …емь»?","choices":["63","64","70","72","80."],"key":"Б","review":["Умножение с пропусками","Восстанови названия чисел. В «де…ять» можно вставить «в» или «с» и получить 9 или 10. В «…емь» можно вставить «с» или «вос» и получить 7 или 8.","Перемножь четыре пары: 9 × 7 = 63, 9 × 8 = 72, 10 × 7 = 70, 10 × 8 = 80. Числа 64 среди результатов нет."]},{"author":"Б. Иомдин","question":"В каком предложении есть ошибка?","choices":["<em>Дружи с тем, с кем играешь.</em>","<em>Играй с теми, с кеми учишься</em>.","<em>Танцуй с теми, кто поёт.</em>","<em>Подпевай тому, кому хочешь</em>.","все предложения правильны."],"key":"Б","review":["Тем, теми и кто","Прочитай «дружи с тем, с кем играешь». Слово «кем» подходит после «с», когда спрашивают, с каким человеком дружат или играют.","При нескольких людях «тем» превращается в «теми», но «кем» остаётся прежним: «Играй с теми, с кем учишься». Ошибка — «с кеми»."]},{"author":"Б. Иомдин","question":"Какой корень в слове <em>спозаранку</em>?","choices":["<em>позаран</em>","<em>зар</em>","<em>ран</em>","<em>заран</em>","в этом слове два корня: <em>поз</em> и <em>ран.</em>"],"key":"В","review":["Корень в слове «спозаранку»","«Спозаранку» означает «рано утром». Сравни его с «рано» и «ранний» и найди общую часть всех трёх слов.","Во всех этих словах повторяется «ран». Эта часть и несёт значение раннего времени, поэтому она корень."]},{"author":"О. Шеманаева","question":"У какого предложения, если поменять в нём местами однородные члены, изменится смысл?","choices":["<em>Он изучает математику и географию</em>.","<em>Когда Серёжа спускается по лестнице, он подпрыгивает и напевает</em>.","<em>Петя встал и позавтракал</em>.","<em>Мы купили ручки и карандаши</em>.","<em>Лёня и Ваня поздравили бабушку с днём рождения</em>."],"key":"В","review":["Порядок слов в предложении","При перестановке предметов покупки или имён детей сами покупки и участники остаются теми же. Подпрыгивать и напевать на лестнице можно одновременно.","«Встал и позавтракал» описывает сначала подъём, потом завтрак. «Позавтракал и встал» меняет порядок событий, поэтому меняется смысл."]},{"author":"И. Рубанов","question":"В старину в военном деле использовали начинённый порохом <em>сосис</em>. Какую форму он имел?","choices":["форму кишки","форму шара","форму блина","форму баранки","форму куба."],"key":"А","review":["Старинное слово «сосис»","Слово «сосис» напоминает «сосиску». Подумай, какой формы оболочку можно наполнить, как сосиску.","Сосис был длинной оболочкой с порохом, похожей на кишку. Шар, блин, баранка и куб не передают эту продолговатую форму."]},{"author":"И. Иткин","question":"Что означает выражение <em>топорная</em> <em>работа</em>?","choices":["‘ремесло плотника’","‘работа, выполненная с помощью одного только топора’","‘работа, которую нельзя выполнить без помощи топора’","‘грубая, неумело выполненная работа’","‘изящная, тонкая работа’."],"key":"Г","review":["Топорная работа","Представь заготовку после грубых ударов топором: остаются сколы, края ещё не обработаны.","По этому образу «топорной» называют грубо и неумело выполненную работу. Так могут оценить даже дело, в котором топор вообще не применяли."]},{"author":"Е. Ренковская","question":"Какое из перечисленных ниже слов не столь «музыкально», как остальные?","choices":["<em>сольдо</em>","<em>миля</em>","<em>сирень</em>","<em>фасоль</em>","<em>доля</em>."],"key":"В","review":["Ноты внутри слов","Раздели слова на названия нот: «соль-до», «ми-ля», «фа-соль», «до-ля». В каждом нашлось по две ноты.","В слове «сирень» есть «си» и «ре», но остаётся лишний кусочек «нь». Целиком собрать это слово из нот нельзя."]},{"author":"А. Иткин и И. Иткин","question":"Какая согласная не может писаться удвоенно?","choices":["<em>в</em>","<em>ж</em>","<em>л</em>","<em>ф</em>","<em>щ</em>."],"key":"Д","review":["Двойные согласные","Подбери примеры: «ввод» пишут с «вв», «жжёт» с «жж», «аллея» с «лл», «эффект» с «фф».","Из списка остаётся «щ». В обычном русском написании её не удваивают: даже долгий звук передаётся одной буквой, как в слове «щука»."]},{"author":"Е. Вельмезова","question":"Что <strong>не</strong> может быть глухим (глухой)?","choices":["ночь","шум","забор","согласный","всё перечисленное в (А)–(Г) может."],"key":"Д","review":["Что бывает глухим","«Глухая ночь» означает глубокую тихую ночь, а «глухой шум» — приглушённый звук. Оба выражения употребляются.","«Глухой забор» — сплошной, без просветов, а «глухой согласный» произносится без голоса. Значит, подходят все четыре примера."]},{"author":"А. Пиперски","question":"Какой знак препинания в «Российской грамматике» М. В. Ломоносова носит название «вместительный»?","choices":["скобки","вопросительный знак","точка с запятой","запятая","двоеточие."],"key":"А","review":["Знак у Ломоносова","В слове «вместительный» слышится «вместить». Ищи знак, у которого есть место для слов внутри.","У скобок две части. Между ними помещают слово, пояснение или целую фразу, отсюда название «вместительный»."]},{"author":"Методкомиссия","question":"Из слова <em>солистка</em>, убрав несколько букв и не меняя порядка оставшихся, можно получить слово <em>лиса</em>. Из всех данных слов таким образом тоже можно получить названия животных, но только в одном из них «спряталось» не одно животное, а два разных. В каком?","choices":["<em>солонка</em>","<em>полдень</em>","<em>полость</em>","<em>корзинка</em>","<em>скорость</em>."],"key":"Д","review":["Звери внутри слов","Оставь буквы в прежнем порядке: «солонка» даёт «слон», «полдень» — «олень», «полость» — «лось», «корзинка» — «коза».","Из «скорость» можно оставить «кот», если взять «к», первое «о» и «т». Если после «к» взять «р», второе «о» и «т», выйдет «крот». Здесь два разных животных."]},{"author":"Б. Иомдин","question":"Сказка «Мальчик-с-пальчик» по-датски называется «Tommeliden». А как называется по-русски сказка Ганса Христиана Андерсена, которую автор по-датски назвал «Tommelise»?","choices":["«Снежная королева»","«Гадкий утёнок»","«Дюймовочка»","«Маленький Тук»","«Свинопас»."],"key":"В","review":["Названия сказок по-датски","Сравни «Tommeliden» и «Tommelise». Общая часть «Tommel-» в датском связана с большим пальцем и подсказывает маленький размер.","Из героев в списке по крошечному росту названа Дюймовочка. Дюйм — небольшая мера длины, исторически связанная с шириной большого пальца."]},{"author":"К. Гилярова","question":"Вот как один маленький мальчик произносит некоторые слова: <em>носок</em> — «сокок», <em>медведь</em> — «двететь», <em>олень</em> — «ленень». Какое слово он произносит как «блютут»?","choices":["<em>верблюд</em>","<em>блюдо</em>","<em>лютик</em>","<em>салют</em>","<em>тюлень</em>."],"key":"А","review":["Как говорит малыш","Прислушайся к концу детских слов: «сок-ок», «двет-еть», «лен-ень». Малыш повторяет последние гласный и согласный.","У слова «верблюд» последний слог звучит как «блют»: конечная «д» оглушается. Повтори два последних звука [у] и [т] и получишь «блют-ут»."]},{"author":"С. Бурлак","question":"Все приведённые ниже слова, кроме одного, состоят из звуков, имеющихся в слове <em>полюс</em>. Кроме какого?","choices":["<em>суп</em>","<em>соль</em>","<em>лось</em>","<em>пульс</em>","<em>плюс</em>."],"key":"В","review":["Звуки слова «полюс»","В «полюс» есть [п], [о], [л’], [у], [с]. Из них можно сложить «суп», «соль», «пульс» и «плюс», меняя порядок.","В «лось» нужны твёрдое [л] и мягкое [с’], а в «полюс» есть мягкое [л’] и твёрдое [с]. Поэтому «лось» не подходит."]},{"author":"Н. Валеева","question":"<em>Галчонок</em>, <em>оленёнок</em>, <em>гусёнок</em>... Какое слово можно добавить в этот список?","choices":["<em>бочонок</em>","<em>цыплёнок</em>","<em>маслёнок</em>","<em>поварёнок</em>","<em>лисёнок</em>."],"key":"Д","review":["Названия детёнышей","Галчонок — детёныш галки, оленёнок — оленя, гусёнок — гуся. Каждое название образовано от названия взрослого животного.","Лисёнок образован от «лиса» точно так же. «Цыплёнок» тоже детёныш, но его название не образуется от слова «курица» или «петух»."]},{"author":"С. Бурлак","question":"В предложении <em>Рубит ёлку лесоруб</em> понятно, что подлежащее — <em>лесоруб</em>. А в каком предложении нельзя однозначно определить, где подлежащее?","choices":["<em>Иванушку любит Василиса</em>.","<em>Дни сменяют ночи</em>.","<em>Вытащил богатырь волшебный меч</em>.","<em>Море горы скрыло</em>.","<em>Копейка рубль бережёт</em>."],"key":"Б","review":["Дни и ночи","В «Иванушку любит Василиса» подлежащее выдают окончания, а в «Море горы скрыло» форма «скрыло» согласуется с «морем».","Формы «дни» и «ночи» одинаковы в именительном и винительном падежах. Поэтому «Дни сменяют ночи» может означать как приход дня после ночи, так и приход ночи после дня."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
